package com.company.tpm.telegram;import com.company.tpm.config.AppProperties;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/telegram")public class TelegramWebhookController{private final AppProperties props;private final TelegramBotClient bot;private final TelegramAccountService accounts;TelegramWebhookController(AppProperties p,TelegramBotClient b,TelegramAccountService a){props=p;bot=b;accounts=a;}
 @PostMapping("/webhook")ResponseEntity<Void> update(@RequestHeader(value="X-Telegram-Bot-Api-Secret-Token",required=false)String secret,@RequestBody Map<String,Object> update){if(!Objects.equals(secret,props.telegram().webhookSecret()))return ResponseEntity.status(403).build();var message=(Map<String,Object>)update.get("message");if(message==null)return ResponseEntity.ok().build();long chat=((Number)((Map<String,Object>)message.get("chat")).get("id")).longValue();long user=((Number)((Map<String,Object>)message.get("from")).get("id")).longValue();String text=String.valueOf(message.getOrDefault("text","")).trim();if(text.equals("/start")){bot.send(chat,"Welcome to TPM Training. Send: LINK <Staff ID> to request account connection.");}else if(text.startsWith("LINK ")){accounts.link(text.substring(5).trim(),user,chat);bot.send(chat,"Account connected. Use /menu to open your training menu.");}else if(text.equals("/disconnect")){accounts.disconnect(user);bot.send(chat,"Telegram account disconnected.");}else{bot.send(chat,"Commands: /start, /menu, /disconnect");}return ResponseEntity.ok().build();}}
